import math

def check_condition(n):
    denominator = 2 * n - 1
    if denominator == 0:
        # Should not happen for non-negative integer n
        return False

    numerator = 3 * (math.factorial(n + 2) + 1)

    if numerator % denominator == 0:
        return True
    else:
        return False

for n in range(9):
    result = check_condition(n)
    print(f"n={n}: {result}")

import math

def calculate_E(n):
    # Denominator: 2n - 1
    denominator = 2 * n - 1
    if denominator == 0:
        # Should not happen for non-negative integer n
        return None 

    # Numerator: 3 * ((n+2)! + 1)
    try:
        factorial_term = math.factorial(n + 2)
        numerator = 3 * (factorial_term + 1)
    except OverflowError:
        # Should not happen for n <= 20
        return float('inf') 

    # Check if division results in an integer
    if numerator % denominator == 0:
        return numerator // denominator
    else:
        return None # Not an integer

solutions = []
for n in range(21): # Check up to n=20
    E_n = calculate_E(n)
    if E_n is not None:
        solutions.append(n)
        # print(f"n={n}: E(n) = {E_n}") # Optional detailed output

print(f"Values of n (0 <= n <= 20) for which E(n) is an integer: {solutions}")

def factorial_mod(k, p):
    res = 1
    for i in range(1, k + 1):
        res = (res * i) % p
    return res

primes = [17, 19, 23, 29, 31]
results = {}
for p in primes:
    k = (p + 5) // 2
    mod_result = factorial_mod(k, p)
    target = p - 1 # We check if k! = -1 mod p
    results[p] = (k, mod_result, target, mod_result == target)

for p, (k, mod_result, target, success) in results.items():
    print(f"p={p}: k={k}. {k}! mod {p} = {mod_result}. Required: {target}. Success: {success}")

